css:
.dwn-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.dwn-root,.dwn-root *,.dwn-root *::before,.dwn-root *::after{box-sizing:border-box}
.dwn-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.dwn-root img{display:block;border:0;max-width:none}
.dwn-root > [data-node-id]{will-change:transform}
.dwn-root [hidden]{display:none!important}
.dwn-root [data-sh-theme="dark"]{display:none!important}
.dwn-root[data-theme="dark"] [data-sh-theme="dark"]{display:block!important}
.dwn-root[data-theme="dark"] [data-sh-theme="dark"]{display:none!important}
.dwn-root .n1_205{align-content:stretch;display:flex;flex:1 0 0;gap:16px;align-items:center;min-width:1px;position:relative}
.dwn-root .n1_206{position:relative;border-radius:16px;flex-shrink:0;width:60px;height:60px}
.dwn-root .x4{position:absolute;inset:0;pointer-events:none;border-radius:16px}
.dwn-root .x5{position:absolute;background-color:var(--wa-bg, #f5f7ff);inset:0;border-radius:16px}
.dwn-root .x6{position:absolute;inset:0;overflow:hidden;border-radius:16px}
.dwn-root .x7{position:absolute;height:116.78%;left:-21.7%;max-width:none;top:-8.18%;width:146.64%}
.dwn-root .n1_207{align-content:stretch;display:flex;flex-direction:column;align-items:flex-start;position:relative;flex-shrink:0;width:131px}
.dwn-root .n1_208{word-break:break-word;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:520;line-height:26px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text, #171d25);font-size:22px;width:131px;white-space:nowrap}
.dwn-root[data-theme="dark"]{color:var(--wa-point, #e3e9f2)}
.dwn-root[data-theme="dark"] [data-name="Header"] > [data-name="Background"]{background:var(--wa-bg, #131519)!important;box-shadow:inset 0 -1px 0 rgba(255,255,255,.06)!important}
.dwn-root[data-theme="dark"] [data-name="Input"],.dwn-root[data-theme="dark"] [data-name="Select"],.dwn-root[data-theme="dark"] [data-name^="Field/ID"],.dwn-root[data-theme="dark"] [data-name^="Field/Password"]{background-color:var(--wa-bg, #111316)}
.dwn-root[data-theme="dark"] [data-name="Widget/Notice"] > div:first-child,.dwn-root[data-theme="dark"] [data-name="Widget/Help Desk"] > div:first-child,.dwn-root[data-theme="dark"] [data-name="Panel"] > div:first-child{background-image:linear-gradient(180deg,color-mix(in srgb, var(--wa-surface, rgb(33 36 43)) 64%, transparent),color-mix(in srgb, var(--wa-bg, rgb(19 21 26)) 76%, transparent))!important;background-color:transparent!important;backdrop-filter:blur(18px) saturate(1.15)!important;-webkit-backdrop-filter:blur(18px) saturate(1.15)!important}
.dwn-root[data-theme="dark"] [data-name="Widget/Notice"] > div:nth-child(3),.dwn-root[data-theme="dark"] [data-name="Widget/Help Desk"] > div:nth-child(3),.dwn-root[data-theme="dark"] [data-name="Panel"] > div:nth-child(3){box-shadow:inset 0 1px 0 rgba(255,255,255,.1),inset 0 0 0 1px rgba(255,255,255,.07),0 24px 48px rgba(0,0,0,.34)!important}
.dwn-root[data-theme="dark"] > [data-node-id]:has([data-name^="Widget/"]) > [data-name="Header"] > [data-name="Background"]{background:color-mix(in srgb, var(--wa-bg, rgb(14 16 20)) 68%, transparent)!important;backdrop-filter:blur(18px)!important;-webkit-backdrop-filter:blur(18px)!important}
.dwn-root[data-theme="dark"] [data-name^="Step/"] > div:first-child{background-color:color-mix(in srgb, var(--wa-point, rgb(130 155 255)) 12%, transparent)}
.dwn-root[data-theme="dark"] [data-name^="Widget/"] [data-name="List Item/Post"]{background-color:color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 4.5%, transparent)}
.dwn-root[data-theme="dark"] [data-name="Count"]{background-color:color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 10%, transparent)!important}
.dwn-root[data-theme="dark"] [data-name="Login Card"] > div:first-child{background-image:linear-gradient(180deg,color-mix(in srgb, var(--wa-surface, rgb(33 36 43)) 62%, transparent),color-mix(in srgb, var(--wa-bg, rgb(19 21 26)) 74%, transparent))!important;background-color:transparent!important;backdrop-filter:blur(18px)!important;-webkit-backdrop-filter:blur(18px)!important}
.dwn-root[data-theme="dark"] [data-name="Login Card"] > div:nth-child(2){box-shadow:inset 0 1px 0 rgba(255,255,255,.12),inset 0 0 0 1px rgba(255,255,255,.08),0 30px 60px rgba(0,0,0,.4)!important}
.dwn-root[data-theme="dark"] [data-name="Search Overlay"] > [data-name="Background"],.dwn-root[data-theme="dark"] [data-name="Background"][data-node-id="1:6533"]{background-color:var(--wa-surface, #17191e)!important}
.dwn-root[data-theme="dark"] .x5{background-color:var(--wa-surface, #23262d)}
.dwn-root[data-theme="dark"] .n1_208{color:var(--wa-text, #eceef2)}
